window.docContents[44].resolve({"/rules/RG1006/#RG1006-proof-shape":{"contents":"A total replacement keeps the same domain and result type; if it changes behavior, state and prove the relation to the intended function.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG1006: Unsafe and partial declarations require exact helper authentication","header":"Required proof shape","id":"/rules/RG1006/#RG1006-proof-shape"},"/rules/RG2005/#RG2005-proof-shape":{"contents":"The replayed declaration must type-check in the kernel with exactly its stated type and value.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG2005: Required admission and source evidence must be complete","header":"Required proof shape","id":"/rules/RG2005/#RG2005-proof-shape"},"/rules/RG4003/#RG4003-proof-shape":{"contents":"No proof obligation: the example demonstrates a rejection. Its pattern is part of the claim and is reviewed with the prose.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG4003: Negative examples require completed intended rejection","header":"Required proof shape","id":"/rules/RG4003/#RG4003-proof-shape"},"/rules/RG5002/#RG5002-proof-shape":{"contents":"No proof obligation: the rule checks presence. The docstring must describe the elaborated statement faithfully.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG5002: Registered public material declarations require docstrings","header":"Required proof shape","id":"/rules/RG5002/#RG5002-proof-shape"}});